import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react"
import "./daytogether.css"
import { calculateSplit } from "./daytogether-calculations.mjs"
import { migrateLegacyState } from "./daytogether-migration.mjs"

type Goal = { id: string; name: string; targetSatang: number; due?: string; status: "active" | "done" | "archived"; color: string }
type Saving = { id: string; kind: "deposit" | "withdraw"; amountSatang: number; date: string; goalId: string; note: string }
type HealthKind = "weight" | "pressure" | "sleep" | "water" | "symptom" | "exercise"
type Health = { id: string; kind: HealthKind; date: string; value: string; extra: string; note: string }
type Note = { id: string; title: string; body: string; kind: "note" | "diary"; date: string; tags: string[]; mood: string; pinned: boolean; archived: boolean; updatedAt: string; version: number }
type Participant = { id: string; name: string; isMe: boolean }
type Expense = { id: string; title: string; amountSatang: number; payerId: string; participantIds: string[]; allocationMode?: "equal" | "fixed" | "percentage"; allocations?: Record<string, number> }
type Settlement = { id: string; fromId: string; toId: string; amountSatang: number; date: string; note: string }
type Bill = { id: string; title: string; date: string; restaurant: string; participants: Participant[]; expenses: Expense[]; settlements: Settlement[]; note: string; bbqId: string; status: "draft" | "settling" | "settled" }
type BillExpenseDraft = { key: string; title: string; amount: string; payerName: string; participantNames: string[] | null; allocationMode: "equal" | "fixed" | "percentage"; allocations: Record<string, string> }
type Visit = { id: string; restaurant: string; title: string; date: string; area: string; friends: string; people: number; totalSatang: number | null; personalSatang: number | null; rating: number | null; menu: string; memory: string; billId: string }
type Settings = { displayName: string; timezone: string; theme: "light" | "dark" | "system"; hidden: boolean; cards: string[]; healthKinds: HealthKind[]; waterGoal: number; heightCm: number | null }
type State = { goals: Goal[]; savings: Saving[]; health: Health[]; notes: Note[]; bills: Bill[]; visits: Visit[]; settings: Settings }
const STORE = "lamoon-daytogether-v1"
const today = (timezone = "Asia/Bangkok") => { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date()); const get = (type: string) => parts.find(part => part.type === type)?.value || "00"; return `${get("year")}-${get("month")}-${get("day")}` }
const dateTimeLocal = (timezone = "Asia/Bangkok") => { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date()); const get = (type: string) => parts.find(part => part.type === type)?.value || "00"; return `${get("year")}-${get("month")}-${get("day")}T${get("hour")}:${get("minute")}` }
const id = () => crypto.randomUUID()
const defaults: State = { goals: [], savings: [], health: [], notes: [], bills: [], visits: [], settings: { displayName: "", timezone: "Asia/Bangkok", theme: "system", hidden: false, cards: ["savings","health","notes","split","bbq"], healthKinds: ["weight","pressure","sleep","water","symptom","exercise"], waterGoal: 2000, heightCm: null } }
function readState(): State { try { return migrateLegacyState(defaults, key => localStorage.getItem(key)) } catch { return defaults } }
const satang = (baht: number) => Math.round(baht * 100)
const money = (value: number, hidden = false) => hidden ? "•••••" : new Intl.NumberFormat("th-TH", { style: "currency", currency: "THB", minimumFractionDigits: 0, maximumFractionDigits: 2 }).format(value / 100)
const dateText = (s: string) => s ? new Date(s.length > 10 ? s : s + "T12:00:00").toLocaleDateString("th-TH", { day: "numeric", month: "short", year: "numeric" }) : "ไม่ระบุวันที่"
const monthKey = (s: string) => s.slice(0,7)
const KIND_LABEL: Record<HealthKind,string> = { weight:"น้ำหนัก", pressure:"ความดัน", sleep:"การนอน", water:"ดื่มน้ำ", symptom:"อาการ / บันทึก", exercise:"ออกกำลังกาย" }
const PAGE_LABEL: Record<string,string> = { "/":"หน้าหลัก","/savings":"ออมเงิน","/health":"สุขภาพ","/notes":"โน้ตและไดอารี","/split":"หารตัง","/bbq":"ประวัติกินหมูกระทะ","/settings":"ตั้งค่า" }
const ICON: Record<string,string> = { "/":"⌂","/savings":"◒","/health":"♡","/notes":"▤","/split":"⇄","/bbq":"♨","/settings":"⚙" }
function amountFrom(value: FormDataEntryValue | null) { const n = Number(value); return Number.isFinite(n) && n >= 0 ? satang(n) : 0 }
function Button({ children, onClick, variant = "secondary", type = "button", disabled = false }: { children: ReactNode; onClick?: () => void; variant?: "primary"|"secondary"|"danger"|"ghost"; type?: "button"|"submit"; disabled?: boolean }) { return <button type={type} disabled={disabled} className={`dt-btn dt-btn-${variant}`} onClick={onClick}>{children}</button> }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="dt-field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }
function Empty({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) { return <div className="dt-empty"><span>✳</span><strong>{title}</strong><p>{detail}</p>{action}</div> }
function responsibility(expenses: Expense[], participantId: string) {
  return expenses.reduce((sum, expense) => {
    const ids = [...new Set(expense.participantIds)];
    const index = ids.indexOf(participantId);
    if (index < 0 || !ids.length) return sum;
    if (expense.allocationMode === "fixed") {
      const value = expense.allocations?.[participantId];
      return sum + (Number.isSafeInteger(value) && (value as number) >= 0 ? value as number : 0);
    }
    if (expense.allocationMode === "percentage") {
      const points = ids.map(id => expense.allocations?.[id]);
      if (points.some(value => !Number.isSafeInteger(value) || (value as number) < 0 || (value as number) > 10000) || points.reduce((total, value) => total + (Number.isSafeInteger(value) ? value as number : 0), 0) !== 10000) return sum;
      const base = Math.floor(expense.amountSatang * (points[index] as number) / 10000);
      const remainder = expense.amountSatang - points.reduce((total, value) => total + Math.floor(expense.amountSatang * (value as number) / 10000), 0);
      return sum + base + (index < remainder ? 1 : 0);
    }
    return sum + Math.floor(expense.amountSatang / ids.length) + (index < expense.amountSatang % ids.length ? 1 : 0);
  }, 0);
}
function escapeCsv(value: unknown) { const s = String(value ?? ""); return /^[\s\u0000-\u001f]*[=+@-]/.test(s) ? "'" + s : s }
function csv(rows: unknown[][]) { return "\uFEFF" + rows.map(row => row.map(value => '"' + escapeCsv(value).replace(/"/g, '""') + '"').join(",")).join("\r\n") }
function download(name: string, content: string, type: string) { const a = document.createElement("a"); const url = URL.createObjectURL(new Blob([content],{type})); a.href = url; a.download=name; a.click(); window.setTimeout(()=>URL.revokeObjectURL(url),1000) }

export default function DayTogether() {
  const [state,setState] = useState<State>(readState)
  const [path,setPath] = useState(window.location.pathname)
  const [moreOpen,setMoreOpen] = useState(false)
  const [modal,setModal] = useState<null|"saving"|"goal"|"health"|"note"|"bill"|"visit">(null)
  const [editId,setEditId] = useState("")
  const [query,setQuery] = useState("")
  const [kindFilter,setKindFilter] = useState("all")
  const [healthRange,setHealthRange] = useState<7 | 30 | 90>(30)
  const [notice,setNotice] = useState("")
  const [draftNote,setDraftNote] = useState({title:"",body:"",kind:"note" as "note"|"diary",date:today(),tags:"",mood:""})
  const [billPeopleText,setBillPeopleText] = useState("")
  const [billDraftExpenses,setBillDraftExpenses] = useState<BillExpenseDraft[]>([])
  const [noteSaving,setNoteSaving] = useState(false)
  const [theme,setTheme] = useState(state.settings.theme)
  const page = path === "/" ? "/" : (Object.keys(PAGE_LABEL).includes(path) ? path : path.startsWith("/savings/goals/") ? "/savings" : path.startsWith("/notes/") ? "/notes" : path.startsWith("/split/") ? "/split" : path.startsWith("/bbq/") ? "/bbq" : "/404")
  const pathParts = path.split("/").filter(Boolean); const routeId = pathParts[pathParts.length - 1] || ""
  useEffect(() => { const pop = () => setPath(window.location.pathname); window.addEventListener("popstate",pop); if(window.location.pathname==="/login"){window.history.replaceState({}, "", "/");setPath("/")} return () => window.removeEventListener("popstate",pop) },[])
  useEffect(() => { try { localStorage.setItem(STORE,JSON.stringify(state)) } catch { setNotice("บันทึกไม่สำเร็จ กรุณาลองใหม่") } },[state])
  useEffect(() => { const media = window.matchMedia("(prefers-color-scheme: dark)"); const applyTheme = () => { document.documentElement.dataset.dtTheme = theme === "system" ? (media.matches ? "dark" : "light") : theme }; applyTheme(); media.addEventListener("change", applyTheme); setState(s=>s.settings.theme===theme?s:{...s,settings:{...s.settings,theme}}); return () => media.removeEventListener("change", applyTheme) },[theme])
  useEffect(() => { if(notice) { const t=window.setTimeout(()=>setNotice(""),3000); return ()=>clearTimeout(t) } },[notice])
  useEffect(() => { const ok=()=>setNotice("บันทึกข้อมูลลงระบบแล้ว"); const fail=(e:Event)=>setNotice("บันทึกไม่สำเร็จ กรุณาลองใหม่"); window.addEventListener("d1-persist-success",ok); window.addEventListener("d1-persist-error",fail); return ()=>{window.removeEventListener("d1-persist-success",ok);window.removeEventListener("d1-persist-error",fail)} },[])
  const go = (next: string) => { if (window.location.pathname !== next) window.history.pushState({}, "", next); setPath(next); setMoreOpen(false); setQuery(""); window.scrollTo({top:0,behavior:"smooth"}) }
  const update = <K extends keyof State>(key: K, value: State[K]) => setState(s=>({...s,[key]:value}))
  const balance = state.savings.reduce((n,t)=>n+(t.kind==="deposit"?t.amountSatang:-t.amountSatang),0)
  const thisMonthSavings = state.savings.filter(t=>monthKey(t.date)===monthKey(today(state.settings.timezone)))
  const totalBillsOpen = state.bills.filter(b=>b.status!=="settled").length
  const amountToReceive = state.bills.reduce((sum,b)=>{const me=b.participants.find(p=>p.isMe);if(!me)return sum;return sum+Math.max(0,calculateSplit(b.expenses,b.participants,b.settlements).balances[me.id]||0)},0)
  const amountToPay = state.bills.reduce((sum,b)=>{const me=b.participants.find(p=>p.isMe);if(!me)return sum;return sum+Math.max(0,-(calculateSplit(b.expenses,b.participants,b.settlements).balances[me.id]||0))},0)
  const monthVisits = state.visits.filter(v=>monthKey(v.date)===monthKey(today(state.settings.timezone)))
  const monthPersonal = monthVisits.reduce((n,v)=>n+(v.personalSatang||0),0)
  const activeGoals = state.goals.filter(g=>g.status==="active")
  const currentNote = state.notes.find(n=>n.id===routeId)
  const currentBill = state.bills.find(b=>b.id===routeId)
  const currentVisit = state.visits.find(v=>v.id===routeId)
  const latestHealth = (kind:HealthKind) => state.health.filter(h=>h.kind===kind).sort((a,b)=>b.date.localeCompare(a.date))[0]
  const openModal = (m: NonNullable<typeof modal>, itemId = "") => {
    setEditId(itemId)
    if (m === "bill") {
      const existing = state.bills.find(b => b.id === itemId)
      setBillPeopleText(existing?.participants.filter(p => !p.isMe).map(p => p.name).join(", ") || "")
      setBillDraftExpenses(existing?.expenses.length ? existing.expenses.map(expense => ({
        key: expense.id, title: expense.title, amount: String(expense.amountSatang / 100),
        payerName: existing.participants.find(p => p.id === expense.payerId)?.name || "ฉัน",
        participantNames: expense.participantIds.map(pid => existing.participants.find(p => p.id === pid)?.name).filter((name): name is string => Boolean(name)),
        allocationMode: expense.allocationMode || "equal",
        allocations: Object.fromEntries(Object.entries(expense.allocations || {}).map(([pid, value]) => {
          const name = existing.participants.find(p => p.id === pid)?.name || ""
          return [name, String(value / 100)]
        }))
      })) : [{key:id(),title:"ค่าอาหาร",amount:"",payerName:"ฉัน",participantNames:null,allocationMode:"equal",allocations:{}}])
    }
    setModal(m)
  }
  const closeModal = () => { setModal(null); setEditId("") }
  const deleteItem = (collection: "goals"|"savings"|"health"|"notes"|"bills"|"visits", itemId: string) => {
    if(!window.confirm("ต้องการลบรายการนี้หรือไม่? การลบนี้ไม่สามารถย้อนกลับได้")) return
    if(collection==="goals") { if(state.savings.some(t=>t.goalId===itemId)) { setNotice("ยังลบเป้าหมายนี้ไม่ได้ เพราะมีรายการออมเชื่อมอยู่"); return } update("goals",state.goals.filter(x=>x.id!==itemId)) }
    else if(collection==="savings") update("savings",state.savings.filter(x=>x.id!==itemId))
    else if(collection==="health") update("health",state.health.filter(x=>x.id!==itemId))
    else if(collection==="notes") update("notes",state.notes.filter(x=>x.id!==itemId))
    else if(collection==="bills") { const bill=state.bills.find(x=>x.id===itemId); if(bill?.settlements.length && !window.confirm("บิลนี้มีประวัติชำระแล้ว ต้องการลบบิลและประวัติชำระหรือไม่?")) return; update("bills",state.bills.filter(x=>x.id!==itemId)); update("visits",state.visits.map(v=>v.billId===itemId?{...v,billId:"",totalSatang:bill?bill.expenses.reduce((n,e)=>n+e.amountSatang,0):v.totalSatang}:v)) }
    else { const v=state.visits.find(x=>x.id===itemId); if(v?.billId && !window.confirm("มื้อนี้เชื่อมกับบิลอยู่ จะเก็บบิลไว้และยกเลิกการเชื่อมหรือไม่?")) return; update("visits",state.visits.filter(x=>x.id!==itemId)); if(v?.billId) update("bills",state.bills.map(b=>b.id===v.billId?{...b,bbqId:""}:b)) }
    setNotice("กำลังบันทึกข้อมูล…")
  }
  const startNote = (note?: Note) => { setDraftNote(note?{title:note.title,body:note.body,kind:note.kind,date:note.date,tags:note.tags.join(", "),mood:note.mood}:{title:"",body:"",kind:"note",date:today(state.settings.timezone),tags:"",mood:""}); openModal("note",note?.id||"") }
  const saveNote = (e:FormEvent<HTMLFormElement>) => { e.preventDefault(); const item:Note={id:editId||id(),title:draftNote.title.trim()||"ไม่มีชื่อ",body:draftNote.body,kind:draftNote.kind,date:draftNote.date,tags:draftNote.tags.split(",").map(s=>s.trim()).filter(Boolean),mood:draftNote.mood,pinned:state.notes.find(n=>n.id===editId)?.pinned||false,archived:state.notes.find(n=>n.id===editId)?.archived||false,updatedAt:new Date().toISOString(),version:(state.notes.find(n=>n.id===editId)?.version||0)+1}; update("notes",editId?state.notes.map(n=>n.id===editId?item:n):[item,...state.notes]); closeModal(); setNotice("กำลังบันทึกข้อมูล…") }
  const createBillFromVisit = (visit:Visit) => { if(visit.billId){go("/split/"+visit.billId);return} const b:Bill={id:id(),title:visit.title||"มื้อหมูกระทะ",date:visit.date,restaurant:visit.restaurant,participants:visit.friends.split(",").map(n=>n.trim()).filter(Boolean).map(name=>({id:id(),name,isMe:false})).concat([{id:id(),name:"ฉัน",isMe:true}]),expenses:visit.totalSatang? [{id:id(),title:"ค่าอาหาร",amountSatang:visit.totalSatang,payerId:"",participantIds:[]}]:[],settlements:[],note:"",bbqId:visit.id,status:"draft"}; b.expenses=b.expenses.map(x=>({...x,payerId:b.participants.find(p=>p.isMe)?.id||"",participantIds:b.participants.map(p=>p.id)})); update("bills",[b,...state.bills]); update("visits",state.visits.map(v=>v.id===visit.id?{...v,billId:b.id}:v)); go("/split/"+b.id); setNotice("กำลังบันทึกข้อมูล…") }
  const linkVisitFromBill = (bill:Bill) => { if(bill.bbqId){go("/bbq/"+bill.bbqId);return} const v:Visit={id:id(),restaurant:bill.restaurant,title:bill.title,date:bill.date,area:"",friends:bill.participants.filter(p=>!p.isMe).map(p=>p.name).join(", "),people:bill.participants.length,totalSatang:bill.expenses.reduce((n,e)=>n+e.amountSatang,0),personalSatang:bill.participants.find(p=>p.isMe)?responsibility(bill.expenses,bill.participants.find(p=>p.isMe)!.id):null,rating:null,menu:"",memory:"",billId:bill.id}; update("visits",[v,...state.visits]); update("bills",state.bills.map(b=>b.id===bill.id?{...b,bbqId:v.id}:b)); go("/bbq/"+v.id); setNotice("กำลังบันทึกข้อมูล…") }
  const pageTitle = page==="/404" ? "ไม่พบหน้า" : (path!==page ? (page==="/notes"?"รายละเอียดโน้ต":page==="/split"?"รายละเอียดบิล":page==="/bbq"?"รายละเอียดมื้อ":"รายละเอียดเป้าหมาย") : PAGE_LABEL[page])
  const navItems = ["/","/savings","/health","/notes","/split","/bbq"]
  const hidden = state.settings.hidden
  const stat = (label:string,value:string,detail:string,icon:string,href:string,accent:string) => <button className={`dt-stat dt-accent-${accent}`} key={label} onClick={()=>go(href)}><span className="dt-stat-icon">{icon}</span><span className="dt-stat-label">{label}</span><strong>{value}</strong><small>{detail}</small></button>
  const recent = [
    ...state.savings.map(t=>({date:t.date,title:(t.kind==="deposit"?"ออมเงิน":"ถอนเงิน"),detail:money(t.amountSatang,hidden),href:"/savings"})),
    ...state.health.map(h=>({date:h.date,title:KIND_LABEL[h.kind],detail:hidden?"•••••":h.value,href:"/health"})),
    ...state.notes.map(n=>({date:n.date,title:n.title,detail:hidden?"ซ่อนเนื้อหา":n.body.slice(0,60),href:"/notes/"+n.id})),
    ...state.bills.map(b=>({date:b.date,title:b.title,detail:b.status==="settled"?"เคลียร์แล้ว":"บิล "+b.status,href:"/split/"+b.id})),
    ...state.visits.map(v=>({date:v.date,title:v.restaurant||v.title,detail:hidden?"•••••":money(v.personalSatang||0),href:"/bbq/"+v.id}))
  ].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6)
  const cardLink = (href:string,title:string,desc:string,icon:string,accent:string) => <button className={`dt-module-card dt-accent-${accent}`} onClick={()=>go(href)} key={href}><span className="dt-module-icon">{icon}</span><span><strong>{title}</strong><small>{desc}</small></span><b>↗</b></button>
  const renderRows = (rows:ReactNode, emptyTitle:string, emptyDetail:string, action?:ReactNode) => <>{rows || <Empty title={emptyTitle} detail={emptyDetail} action={action}/>}</>
  const pageBody = () => {
    if(page==="/404") return <Empty title="ไม่พบหน้าที่ต้องการ" detail="ลิงก์นี้อาจถูกลบหรือเปลี่ยนไปแล้ว" action={<Button variant="primary" onClick={()=>go("/")}>กลับหน้าหลัก</Button>}/>
    if(page==="/") return <div className="dt-page-body">
      <section className="dt-welcome"><div><span className="dt-eyebrow">พื้นที่ส่วนตัวของคุณ</span><h2>สวัสดี{state.settings.displayName? " "+state.settings.displayName:""} 👋</h2><p>{new Date().toLocaleDateString("th-TH",{weekday:"long",day:"numeric",month:"long",year:"numeric",timeZone:state.settings.timezone})} · ค่อย ๆ จัดการเรื่องของตัวเองในแบบที่สบายใจ</p></div><Button variant="primary" onClick={()=>setMoreOpen(v=>!v)}>＋ เพิ่มรายการ</Button></section>
      <div className="dt-stat-grid">{state.settings.cards.includes("savings")&&stat("ยอดออมที่บันทึก",money(balance,hidden),`ฝากเดือนนี้ ${money(thisMonthSavings.filter(t=>t.kind==="deposit").reduce((n,t)=>n+t.amountSatang,0),hidden)}`,"◒","/savings","green")}{state.settings.cards.includes("health")&&stat("น้ำหนักล่าสุด",latestHealth("weight")?(hidden?"•••••":latestHealth("weight")!.value+" กก."):"ยังไม่มีข้อมูล",latestHealth("weight")?"วัดเมื่อ "+dateText(latestHealth("weight")!.date):"เริ่มบันทึกสุขภาพ","♡","/health","blue")}{state.settings.cards.includes("notes")&&stat("โน้ตและไดอารี",String(state.notes.filter(n=>!n.archived).length)+" รายการ",state.notes.some(n=>n.pinned)?"มีโน้ตปักหมุด":"เก็บความคิดไว้ในที่เดียว","▤","/notes","purple")}{state.settings.cards.includes("split")&&stat("หารตัง · ต้องรับ",money(amountToReceive,hidden),"ต้องจ่าย "+money(amountToPay,hidden)+" · "+totalBillsOpen+" บิลยังไม่เคลียร์","⇄","/split","navy")}{state.settings.cards.includes("bbq")&&stat("มื้อหมูกระทะเดือนนี้",String(monthVisits.length)+" มื้อ","ค่าใช้จ่ายส่วนตัว "+money(monthPersonal,hidden),"♨","/bbq","orange")}</div>
      <section className="dt-section"><div className="dt-section-head"><div><h3>ทางลัด</h3><p>เลือกหมวดที่ต้องการบันทึก</p></div></div><div className="dt-module-grid">{cardLink("/savings","ออมเงิน","เป้าหมายและรายการออม","◒","green")}{cardLink("/health","สุขภาพ","น้ำหนัก การนอน และอื่น ๆ","♡","blue")}{cardLink("/notes","โน้ต / ไดอารี","ความคิดและความทรงจำ","▤","purple")}{cardLink("/split","หารตัง","แบ่งค่าใช้จ่ายกับเพื่อน","⇄","navy")}{cardLink("/bbq","ประวัติกินหมูกระทะ","ร้าน มื้อ และความทรงจำ","♨","orange")}</div></section>
      <section className="dt-section"><div className="dt-section-head"><div><h3>รายการล่าสุด</h3><p>สรุปจากข้อมูลที่คุณบันทึก</p></div></div>{recent.length?<div className="dt-recent-list">{recent.map((r,i)=><button className="dt-recent" key={r.title+i} onClick={()=>go(r.href)}><span className="dt-recent-mark">{i+1}</span><span><strong>{hidden&&r.href.startsWith("/notes")?"ซ่อนเนื้อหา":r.title}</strong><small>{dateText(r.date)} · {r.detail}</small></span><b>↗</b></button>)}</div>:<Empty title="เริ่มต้นพื้นที่ส่วนตัวของคุณ" detail="เพิ่มรายการแรก แล้วภาพรวมจะค่อย ๆ แสดงข้อมูลที่คุณบันทึก" action={<Button variant="primary" onClick={()=>openModal("saving")}>เพิ่มเงินออม</Button>}/>}</section>
      {totalBillsOpen>0&&<section className="dt-callout"><span>↔</span><div><strong>มีบิลที่ยังไม่เคลียร์ {totalBillsOpen} บิล</strong><p>เปิดดูว่าใครต้องรับหรือจ่ายเงิน</p></div><Button onClick={()=>go("/split")}>ดูบิล</Button></section>}
    </div>
    if(page==="/savings") {
      const targetBalance=(goalId:string)=>state.savings.filter(t=>t.goalId===goalId).reduce((n,t)=>n+(t.kind==="deposit"?t.amountSatang:-t.amountSatang),0)
      const rows=state.savings.filter(t=>(kindFilter==="all"||t.kind===kindFilter)&&(!query||t.note.toLowerCase().includes(query.toLowerCase())||state.goals.find(g=>g.id===t.goalId)?.name.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date))
      return <div className="dt-page-body"><div className="dt-stat-grid three">{stat("ยอดคงเหลือ",money(balance,hidden),"คำนวณจากรายการฝากและถอน","◒","/savings","green")}{stat("ฝากเดือนนี้",money(thisMonthSavings.filter(t=>t.kind==="deposit").reduce((n,t)=>n+t.amountSatang,0),hidden),"รายการที่บันทึกในเดือนนี้","＋","/savings","green")}{stat("ถอนเดือนนี้",money(thisMonthSavings.filter(t=>t.kind==="withdraw").reduce((n,t)=>n+t.amountSatang,0),hidden),"รายการที่บันทึกในเดือนนี้","−","/savings","orange")}</div><p className="dt-disclaimer">ยอดจากรายการที่คุณบันทึก ไม่ได้เชื่อมต่อบัญชีธนาคาร</p>
      <section className="dt-section"><div className="dt-section-head"><div><h3>เป้าหมายออมเงิน</h3><p>ติดตามสิ่งที่อยากเก็บเงินไว้</p></div><Button variant="primary" onClick={()=>openModal("goal")}>＋ สร้างเป้าหมาย</Button></div>{state.goals.length?<div className="dt-goal-grid">{state.goals.filter(g=>g.status!=="archived").map(g=>{const saved=targetBalance(g.id),pct=Math.min(100,Math.max(0,Math.round(saved/g.targetSatang*100)));return <article className="dt-goal-card" key={g.id}><div className="dt-goal-top"><span className={"dt-goal-dot "+g.color}/><span className="dt-pill">{g.status==="done"?"สำเร็จ":g.status==="archived"?"เก็บถาวร":"กำลังออม"}</span><button className="dt-icon-button" aria-label="แก้ไขเป้าหมาย" onClick={()=>openModal("goal",g.id)}>···</button></div><h4>{g.name}</h4><strong className="dt-goal-amount">{money(saved,hidden)} <small>/ {money(g.targetSatang,hidden)}</small></strong><div className="dt-progress"><i style={{width:pct+"%"}}/></div><div className="dt-between"><small>{pct}% ของเป้าหมาย</small><small>{g.due?"เป้าหมาย "+dateText(g.due):"ไม่กำหนดวัน"}</small></div><div className="dt-actions"><Button onClick={()=>{setKindFilter("deposit");openModal("saving")}}>＋ ฝากออม</Button><Button onClick={()=>{setKindFilter("withdraw");openModal("saving")}}>ถอน</Button><Button onClick={()=>go("/savings/goals/"+g.id)}>รายละเอียด</Button></div></article>})}</div>:<Empty title="ยังไม่มีเป้าหมาย" detail="สร้างเป้าหมายแรกเพื่อเริ่มติดตามความคืบหน้า" action={<Button variant="primary" onClick={()=>openModal("goal")}>สร้างเป้าหมาย</Button>}/>}</section>
      <section className="dt-section"><div className="dt-section-head"><div><h3>ประวัติการออม</h3><p>เพิ่ม แก้ไข หรือลบรายการได้</p></div><Button variant="primary" onClick={()=>openModal("saving")}>＋ เพิ่มรายการ</Button></div><div className="dt-toolbar"><input aria-label="ค้นหารายการออม" placeholder="ค้นหาหมายเหตุหรือเป้าหมาย" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="กรองประเภท" value={kindFilter} onChange={e=>setKindFilter(e.target.value)}><option value="all">ทุกประเภท</option><option value="deposit">ฝากออม</option><option value="withdraw">ถอน</option></select></div>{rows.length?<div className="dt-list">{rows.map(t=><article className="dt-list-row" key={t.id}><span className="dt-list-icon">{t.kind==="deposit"?"＋":"−"}</span><div className="dt-list-copy"><strong>{t.kind==="deposit"?"ฝากออม":"ถอนเงิน"}{t.goalId?" · "+(state.goals.find(g=>g.id===t.goalId)?.name||"เป้าหมายที่ถูกลบ"):" · ออมทั่วไป"}</strong><small>{dateText(t.date)}{t.note?" · "+t.note:""}</small></div><strong className={t.kind==="deposit"?"dt-positive":"dt-negative"}>{t.kind==="deposit"?"+":"−"}{money(t.amountSatang,hidden)}</strong><Button onClick={()=>openModal("saving",t.id)}>แก้ไข</Button><Button variant="danger" onClick={()=>deleteItem("savings",t.id)}>ลบ</Button></article>)}</div>:<Empty title="ยังไม่มีรายการออม" detail="เพิ่มเงินฝากออมรายการแรกได้เลย" action={<Button variant="primary" onClick={()=>openModal("saving")}>เพิ่มรายการ</Button>}/>}</section></div>
    }
    if(page==="/health") {
      const entries=state.health.filter(h=>(kindFilter==="all"||h.kind===kindFilter)&&(!query||(h.value+" "+h.note+" "+h.extra).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date))
      const waterToday=state.health.filter(h=>h.kind==="water"&&h.date.slice(0,10)===today(state.settings.timezone)).reduce((n,h)=>n+Number(h.value||0),0)
      const trendKind:HealthKind=(["weight","water","sleep"].includes(kindFilter)?kindFilter:"weight") as HealthKind
      const cutoff=new Date();cutoff.setDate(cutoff.getDate()-healthRange+1)
      const cutoffKey=`${cutoff.getFullYear()}-${String(cutoff.getMonth()+1).padStart(2,"0")}-${String(cutoff.getDate()).padStart(2,"0")}`
      const trendRows=state.health.filter(h=>h.kind===trendKind&&h.date.slice(0,10)>=cutoffKey&&h.date.slice(0,10)<=today(state.settings.timezone)&&h.value.trim()!==""&&Number.isFinite(Number(h.value))).sort((a,b)=>a.date.localeCompare(b.date))
      const trendByDay=new Map<string,number>()
      for(const row of trendRows){const key=row.date.slice(0,10);const value=Number(row.value);trendByDay.set(key,trendKind==="water"?(trendByDay.get(key)||0)+value:value)}
      const trendPoints=[...trendByDay.entries()].map(([date,value])=>({date,value})).sort((a,b)=>a.date.localeCompare(b.date))
      const trendMin=trendPoints.length?Math.min(...trendPoints.map(point=>point.value)):0
      const trendMax=trendPoints.length?Math.max(...trendPoints.map(point=>point.value)):1
      const trendCoords=trendPoints.map((point,index)=>({ ...point,x:trendPoints.length===1?350:20+index*660/(trendPoints.length-1),y:160-(trendMax===trendMin?0.5:(point.value-trendMin)/(trendMax-trendMin))*120 }))
      const trendUnit=trendKind==="weight"?"กก.":trendKind==="water"?"mL":"ชม."
      const latestWeight=latestHealth("weight")
      const bmiValue=latestWeight&&Number(latestWeight.value)>0&&state.settings.heightCm&&state.settings.heightCm>0?Number(latestWeight.value)/Math.pow(state.settings.heightCm/100,2):null
      return <div className="dt-page-body"><div className="dt-health-disclaimer">เครื่องมือนี้มีไว้บันทึกและดูแนวโน้ม ไม่ใช่การวินิจฉัยทางการแพทย์</div><section className="dt-section"><div className="dt-section-head"><div><h3>หมวดที่ติดตาม</h3><p>เลือกเฉพาะข้อมูลที่คุณอยากบันทึก</p></div><Button variant="primary" onClick={()=>openModal("health")}>＋ บันทึกสุขภาพ</Button></div><div className="dt-health-kind-grid">{state.settings.healthKinds.map(k=><button className="dt-health-kind" key={k} onClick={()=>{setKindFilter(k);setModal("health")}}><span>{({weight:"⚖",pressure:"⌁",sleep:"☾",water:"♧",symptom:"✎",exercise:"↗"} as Record<HealthKind,string>)[k]}</span><strong>{KIND_LABEL[k]}</strong><small>{latestHealth(k)?dateText(latestHealth(k)!.date):"ยังไม่มีข้อมูล"}</small></button>)}</div></section><div className="dt-stat-grid four">{stat("น้ำดื่มวันนี้",waterToday+" mL","เป้าหมายส่วนตัว "+state.settings.waterGoal+" mL","♧","/health","green")}{stat("รายการสุขภาพ",String(state.health.length),"ทุกหมวดที่บันทึก","♡","/health","green")}{stat("น้ำหนักล่าสุด",latestWeight?(hidden?"•••••":latestWeight.value+" กก."):"—",latestWeight?dateText(latestWeight.date):"ยังไม่มีข้อมูล","⚖","/health","green")}{stat("BMI",hidden&&bmiValue!==null?"•••••":bmiValue===null?"ยังคำนวณไม่ได้":bmiValue.toFixed(1),bmiValue===null?"กรอกส่วนสูงและน้ำหนักล่าสุด":"คำนวณจากส่วนสูง "+state.settings.heightCm+" ซม.","↗","/health","green")}</div><section className="dt-section dt-health-trend"><div className="dt-section-head"><div><h3>แนวโน้มสุขภาพ</h3><p>{KIND_LABEL[trendKind]} · ย้อนหลัง {healthRange} วัน</p></div><div className="dt-range-tabs">{([7,30,90] as const).map(range=><Button key={range} variant={healthRange===range?"primary":"ghost"} onClick={()=>setHealthRange(range)}>{range} วัน</Button>)}</div></div>{hidden?<p className="dt-disclaimer">กราฟถูกซ่อนเมื่อเปิดโหมดความเป็นส่วนตัว</p>:trendCoords.length?<><div className="dt-health-chart-wrap"><svg className="dt-health-chart" viewBox="0 0 700 190" role="img" aria-label={`แนวโน้ม${KIND_LABEL[trendKind]}ย้อนหลัง ${healthRange} วัน`}><line x1="20" y1="160" x2="680" y2="160" stroke="currentColor" opacity=".15"/>{trendCoords.length>1&&<polyline points={trendCoords.map(point=>`${point.x},${point.y}`).join(" ")} fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>}{trendCoords.map(point=><circle key={point.date} cx={point.x} cy={point.y} r="4" fill="currentColor"><title>{dateText(point.date)}: {point.value} {trendUnit}</title></circle>)}</svg></div><div className="dt-between dt-trend-labels"><small>{dateText(trendCoords[0].date)}</small><strong>{trendCoords[trendCoords.length-1].value.toLocaleString("th-TH")} {trendUnit}</strong><small>{dateText(trendCoords[trendCoords.length-1].date)}</small></div></>:<Empty title="ยังไม่มีข้อมูลตัวเลขในช่วงนี้" detail="บันทึกน้ำหนัก น้ำดื่ม หรือชั่วโมงนอนเพื่อดูแนวโน้ม"/>}</section><section className="dt-section"><div className="dt-section-head"><div><h3>ประวัติสุขภาพ</h3><p>ค่าจริงตามวันที่บันทึก</p></div></div><div className="dt-toolbar"><input aria-label="ค้นหาประวัติสุขภาพ" placeholder="ค้นหาค่าหรือหมายเหตุ" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="กรองหมวดสุขภาพ" value={kindFilter} onChange={e=>setKindFilter(e.target.value)}><option value="all">ทุกหมวด</option>{state.settings.healthKinds.map(k=><option key={k} value={k}>{KIND_LABEL[k]}</option>)}</select></div>{entries.length?<div className="dt-list">{entries.map(h=><article className="dt-list-row" key={h.id}><span className="dt-list-icon">{({weight:"⚖",pressure:"⌁",sleep:"☾",water:"♧",symptom:"✎",exercise:"↗"} as Record<HealthKind,string>)[h.kind]}</span><div className="dt-list-copy"><strong>{KIND_LABEL[h.kind]} · {hidden?"•••••":h.value}</strong><small>{dateText(h.date)}{h.extra?" · "+h.extra:""}{h.note?" · "+h.note:""}</small></div><Button onClick={()=>openModal("health",h.id)}>แก้ไข</Button><Button variant="danger" onClick={()=>deleteItem("health",h.id)}>ลบ</Button></article>)}</div>:<Empty title="ยังไม่มีบันทึกสุขภาพ" detail="เลือกหมวดที่ต้องการติดตาม แล้วบันทึกได้ตามสะดวก" action={<Button variant="primary" onClick={()=>openModal("health")}>บันทึกสุขภาพ</Button>}/>}</section></div>
    }
    if(page==="/notes") {
      const notes=state.notes.filter(n=>!n.archived&&(kindFilter==="all"||n.kind===kindFilter)&&(!query||(n.title+" "+n.body+" "+n.tags.join(" ")).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updatedAt.localeCompare(a.updatedAt))
      if(path!=="/notes") return currentNote?<div className="dt-page-body"><Button onClick={()=>go("/notes")}>← กลับรายการโน้ต</Button><article className="dt-detail-card"><div className="dt-detail-top"><span className="dt-pill">{currentNote.kind==="diary"?"ไดอารี":"โน้ต"}</span><span>{dateText(currentNote.date)}</span></div><h2>{hidden?"ซ่อนเนื้อหา":currentNote.title}</h2><div className="dt-note-body">{hidden?"เนื้อหาถูกซ่อนในโหมดความเป็นส่วนตัว":currentNote.body||"ไม่มีเนื้อหา"}</div><div className="dt-tag-row">{currentNote.tags.map(t=><span className="dt-tag" key={t}>{t}</span>)}</div><div className="dt-actions"><Button variant="primary" onClick={()=>startNote(currentNote)}>แก้ไข</Button><Button onClick={()=>update("notes",state.notes.map(n=>n.id===currentNote.id?{...n,pinned:!n.pinned}:n))}>{currentNote.pinned?"เลิกปักหมุด":"ปักหมุด"}</Button><Button onClick={()=>update("notes",state.notes.map(n=>n.id===currentNote.id?{...n,archived:!n.archived}:n))}>{currentNote.archived?"นำออกจากคลัง":"เก็บถาวร"}</Button><Button variant="danger" onClick={()=>deleteItem("notes",currentNote.id)}>ลบ</Button></div></article></div>:<Empty title="ไม่พบโน้ตนี้" detail="รายการอาจถูกลบไปแล้ว" action={<Button onClick={()=>go("/notes")}>กลับรายการโน้ต</Button>}/>
      return <div className="dt-page-body"><section className="dt-section"><div className="dt-section-head"><div><h3>พื้นที่ความคิดของคุณ</h3><p>โน้ตและไดอารีเป็นส่วนตัวเสมอ</p></div><Button variant="primary" onClick={()=>startNote()}>＋ เขียนบันทึก</Button></div><div className="dt-toolbar"><input aria-label="ค้นหาโน้ต" placeholder="ค้นหาหัวข้อ เนื้อหา หรือแท็ก" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="กรองประเภทโน้ต" value={kindFilter} onChange={e=>setKindFilter(e.target.value)}><option value="all">ทั้งหมด</option><option value="note">โน้ต</option><option value="diary">ไดอารี</option></select></div>{notes.length?<div className="dt-note-grid">{notes.map(n=><article className="dt-note-card" key={n.id}><div className="dt-note-top"><span className="dt-pill">{n.kind==="diary"?"ไดอารี":"โน้ต"}</span>{n.pinned&&<span className="dt-pin">ปักหมุด</span>}<button className="dt-icon-button" aria-label="แก้ไขโน้ต" onClick={()=>startNote(n)}>···</button></div><button className="dt-note-open" onClick={()=>go("/notes/"+n.id)}><strong>{hidden?"ซ่อนเนื้อหา":n.title}</strong><p>{hidden?"เนื้อหาถูกซ่อน":n.body||"ไม่มีเนื้อหา"}</p></button><div className="dt-tag-row">{n.tags.map(t=><span className="dt-tag" key={t}>{t}</span>)}</div><div className="dt-between"><small>{dateText(n.date)}</small><small>แก้ไข {new Date(n.updatedAt).toLocaleDateString("th-TH")}</small></div></article>)}</div>:<Empty title="เริ่มจดบันทึกแรก" detail="จดไอเดีย ความทรงจำ หรือความรู้สึกของวันนี้" action={<Button variant="primary" onClick={()=>startNote()}>เขียนบันทึก</Button>}/>}</section></div>
    }
    if(page==="/split") {
      if(path!=="/split") return currentBill?<BillDetail bill={currentBill} hidden={hidden} onBack={()=>go("/split")} onEdit={()=>openModal("bill",currentBill.id)} onDelete={()=>deleteItem("bills",currentBill.id)} onSaveSettlement={(from,to,amount,note)=>{const fresh=state.bills.find(b=>b.id===currentBill.id);if(!fresh)return;const summary=calculateSplit(fresh.expenses,fresh.participants,fresh.settlements);if((summary.balances[from]||0)>=0||(summary.balances[to]||0)<=0){setNotice("เลือกผู้โอนที่ยังต้องจ่ายและผู้รับที่ต้องรับเงิน");return}const remaining=Math.max(0,Math.min(amount,-(summary.balances[from]||0),summary.balances[to]||0));if(!remaining){setNotice("จำนวนเงินเกินยอดที่ต้องเคลียร์");return}const settlements=[...fresh.settlements,{id:id(),fromId:from,toId:to,amountSatang:remaining,date:today(state.settings.timezone),note}];const nextSummary=calculateSplit(fresh.expenses,fresh.participants,settlements);update("bills",state.bills.map(b=>b.id===fresh.id?{...b,settlements,status:nextSummary.transfers.length?"settling":"settled"}:b));setNotice("กำลังบันทึกข้อมูล…")}} onLinkVisit={()=>linkVisitFromBill(currentBill)} onCancelSettlement={sid=>{update("bills",state.bills.map(b=>b.id===currentBill.id?{...b,settlements:b.settlements.filter(s=>s.id!==sid),status:"settling"}:b));setNotice("กำลังบันทึกข้อมูล…")}}/>:<Empty title="ไม่พบบิลนี้" detail="บิลอาจถูกลบไปแล้ว" action={<Button onClick={()=>go("/split")}>กลับหน้าหารตัง</Button>}/>
      return <div className="dt-page-body"><section className="dt-section"><div className="dt-section-head"><div><h3>บิลของคุณ</h3><p>เพื่อนไม่จำเป็นต้องมีบัญชี</p></div><Button variant="primary" onClick={()=>openModal("bill")}>＋ สร้างบิล</Button></div><div className="dt-toolbar"><input aria-label="ค้นหาบิล" placeholder="ค้นหาชื่อบิลหรือร้าน" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="กรองสถานะบิล" value={kindFilter} onChange={e=>setKindFilter(e.target.value)}><option value="all">ทุกสถานะ</option><option value="draft">ร่าง</option><option value="settling">กำลังเคลียร์</option><option value="settled">เคลียร์แล้ว</option></select></div>{state.bills.filter(b=>(kindFilter==="all"||b.status===kindFilter)&&(!query||(b.title+" "+b.restaurant).toLowerCase().includes(query.toLowerCase()))).length?<div className="dt-bill-list">{state.bills.filter(b=>(kindFilter==="all"||b.status===kindFilter)&&(!query||(b.title+" "+b.restaurant).toLowerCase().includes(query.toLowerCase()))).map(b=><button className="dt-bill-row" key={b.id} onClick={()=>go("/split/"+b.id)}><span className="dt-list-icon">⇄</span><span className="dt-list-copy"><strong>{b.title}</strong><small>{dateText(b.date)} · {b.participants.length} คน · {b.restaurant||"ไม่ระบุร้าน"}</small></span><strong>{money(b.expenses.reduce((n,e)=>n+e.amountSatang,0),hidden)}</strong><span className={"dt-pill "+b.status}>{b.status==="settled"?"เคลียร์แล้ว":b.status==="settling"?"กำลังเคลียร์":"ร่าง"}</span></button>)}</div>:<Empty title="ยังไม่มีบิล" detail="สร้างบิลแล้วเพิ่มคนและรายการค่าใช้จ่าย" action={<Button variant="primary" onClick={()=>openModal("bill")}>สร้างบิล</Button>}/>}</section></div>
    }
    if(page==="/bbq") {
      if(path!=="/bbq") return currentVisit?<div className="dt-page-body"><Button onClick={()=>go("/bbq")}>← กลับประวัติ</Button><article className="dt-detail-card"><div className="dt-detail-top"><span className="dt-pill">มื้ออาหาร</span><span>{dateText(currentVisit.date)}</span></div><h2>{currentVisit.restaurant||currentVisit.title}</h2><p>{currentVisit.title}</p><div className="dt-stat-grid three"><div className="dt-inline-stat"><small>ยอดรวมมื้อ</small><strong>{currentVisit.totalSatang===null?"ยังไม่ระบุ":money(currentVisit.totalSatang,hidden)}</strong></div><div className="dt-inline-stat"><small>ค่าใช้จ่ายส่วนตัว</small><strong>{currentVisit.personalSatang===null?"ยังไม่ทราบ":money(currentVisit.personalSatang,hidden)}</strong></div><div className="dt-inline-stat"><small>คะแนน</small><strong>{currentVisit.rating===null?"ยังไม่ให้คะแนน":currentVisit.rating+" / 5"}</strong></div></div><p>{currentVisit.area} {currentVisit.friends&&"· ไปกับ "+currentVisit.friends}</p><h3>เมนูที่ชอบ</h3><p>{currentVisit.menu||"ยังไม่มีข้อมูล"}</p><h3>ความทรงจำ</h3><p>{hidden?"เนื้อหาถูกซ่อน":currentVisit.memory||"ยังไม่มีบันทึก"}</p><div className="dt-actions">{currentVisit.billId?<Button variant="primary" onClick={()=>go("/split/"+currentVisit.billId)}>เปิดบิลที่เชื่อม</Button>:<Button variant="primary" onClick={()=>createBillFromVisit(currentVisit)}>สร้างบิลหารตังจากมื้อนี้</Button>}<Button onClick={()=>openModal("visit",currentVisit.id)}>แก้ไข</Button><Button variant="danger" onClick={()=>deleteItem("visits",currentVisit.id)}>ลบ</Button></div></article></div>:<Empty title="ไม่พบมื้อนี้" detail="ประวัติมื้อนี้อาจถูกลบไปแล้ว" action={<Button onClick={()=>go("/bbq")}>กลับประวัติ</Button>}/>
      return <div className="dt-page-body"><div className="dt-stat-grid three">{stat("มื้อเดือนนี้",String(monthVisits.length),"มื้อที่บันทึกในเดือนนี้","♨","/bbq","orange")}{stat("ค่าใช้จ่ายส่วนตัว",money(monthPersonal,hidden),"เฉพาะมื้อที่ระบุค่าใช้จ่ายส่วนตัว","฿","/bbq","orange")}{stat("เฉลี่ยต่อมื้อ",monthVisits.filter(v=>v.personalSatang!==null).length?money(Math.round(monthPersonal/monthVisits.filter(v=>v.personalSatang!==null).length),hidden):"ยังไม่มีข้อมูล","จากมื้อที่มีค่าใช้จ่ายส่วนตัว","∿","/bbq","orange")}</div><section className="dt-section"><div className="dt-section-head"><div><h3>ความทรงจำบนโต๊ะหมูกระทะ</h3><p>เก็บร้าน มื้ออาหาร และเรื่องราวไว้ดูย้อนหลัง</p></div><Button variant="primary" onClick={()=>openModal("visit")}>＋ เพิ่มมื้อ</Button></div><div className="dt-toolbar"><input aria-label="ค้นหาประวัติมื้อ" placeholder="ค้นหาร้านหรือชื่อมื้อ" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="กรองคะแนน" value={kindFilter} onChange={e=>setKindFilter(e.target.value)}><option value="all">ทุกคะแนน</option>{[5,4,3,2,1].map(n=><option value={String(n)} key={n}>{n} ดาว</option>)}</select></div>{state.visits.filter(v=>(kindFilter==="all"||String(v.rating)===kindFilter)&&(!query||(v.restaurant+" "+v.title+" "+v.memory).toLowerCase().includes(query.toLowerCase()))).length?<div className="dt-visit-grid">{state.visits.filter(v=>(kindFilter==="all"||String(v.rating)===kindFilter)&&(!query||(v.restaurant+" "+v.title+" "+v.memory).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)).map(v=><article className="dt-visit-card" key={v.id}><div className="dt-visit-art">♨<span>{dateText(v.date)}</span></div><div className="dt-visit-content"><h4>{v.restaurant||v.title}</h4><p>{v.title||"มื้อธรรมดาที่น่าจำ"}{v.rating?" · "+"★".repeat(v.rating):""}</p><div className="dt-between"><small>{v.people} คน</small><strong>{v.personalSatang===null?"ค่าใช้จ่ายส่วนตัวไม่ทราบ":money(v.personalSatang,hidden)}</strong></div><div className="dt-actions"><Button onClick={()=>go("/bbq/"+v.id)}>ดูรายละเอียด</Button><Button onClick={()=>openModal("visit",v.id)}>แก้ไข</Button></div></div></article>)}</div>:<Empty title="ยังไม่มีประวัติมื้ออาหาร" detail="บันทึกร้านที่ไปกับเพื่อนและความทรงจำของมื้อนั้น" action={<Button variant="primary" onClick={()=>openModal("visit")}>เพิ่มมื้อแรก</Button>}/>}</section></div>
    }
    if(page==="/settings") return <div className="dt-page-body"><section className="dt-section dt-settings-card"><h3>โปรไฟล์และการแสดงผล</h3><p>ตั้งค่าพื้นที่ส่วนตัวของคุณ</p><form className="dt-form-grid" onSubmit={e=>{e.preventDefault();setNotice("กำลังบันทึกข้อมูล…")}}><Field label="ชื่อแสดงผล"><input value={state.settings.displayName} onChange={e=>setState(s=>({...s,settings:{...s.settings,displayName:e.target.value}}))} placeholder="ชื่อเล่น (ไม่บังคับ)"/></Field><Field label="ธีม"><select value={theme} onChange={e=>setTheme(e.target.value as Settings["theme"])}><option value="system">ตามระบบ</option><option value="light">สว่าง</option><option value="dark">มืด</option></select></Field><Field label="เขตเวลา"><select value={state.settings.timezone} onChange={e=>setState(s=>({...s,settings:{...s.settings,timezone:e.target.value}}))}><option value="Asia/Bangkok">ประเทศไทย (Asia/Bangkok)</option><option value="Asia/Tokyo">ญี่ปุ่น (Asia/Tokyo)</option><option value="UTC">UTC</option></select></Field><Field label="ส่วนสูง (ซม.) สำหรับคำนวณ BMI"><input type="number" min="50" max="250" step="0.1" value={state.settings.heightCm??""} onChange={e=>setState(s=>({...s,settings:{...s.settings,heightCm:e.target.value===""?null:Number(e.target.value)}}))} placeholder="เช่น 170"/></Field><Field label="เป้าหมายน้ำดื่มรายวัน (mL)"><input type="number" min="0" max="10000" value={state.settings.waterGoal} onChange={e=>setState(s=>({...s,settings:{...s.settings,waterGoal:Number(e.target.value)||0}}))}/></Field><Button variant="primary" type="submit">บันทึกการตั้งค่า</Button></form></section><section className="dt-section dt-settings-card"><h3>การ์ดบนหน้าหลัก</h3><div className="dt-check-grid">{["savings","health","notes","split","bbq"].map(k=><label key={k}><input type="checkbox" checked={state.settings.cards.includes(k)} onChange={e=>setState(s=>({...s,settings:{...s.settings,cards:e.target.checked?[...s.settings.cards,k]:s.settings.cards.filter(x=>x!==k)}}))}/>{({savings:"ออมเงิน",health:"สุขภาพ",notes:"โน้ต",split:"หารตัง",bbq:"หมูกระทะ"} as Record<string,string>)[k]}</label>)}</div><h3>หมวดสุขภาพที่ติดตาม</h3><div className="dt-check-grid">{(Object.keys(KIND_LABEL) as HealthKind[]).map(k=><label key={k}><input type="checkbox" checked={state.settings.healthKinds.includes(k)} onChange={e=>setState(s=>({...s,settings:{...s.settings,healthKinds:e.target.checked?[...s.settings.healthKinds,k]:s.settings.healthKinds.filter(x=>x!==k)}}))}/>{KIND_LABEL[k]}</label>)}</div><label className="dt-check-line"><input type="checkbox" checked={hidden} onChange={e=>setState(s=>({...s,settings:{...s.settings,hidden:e.target.checked}}))}/> ซ่อนตัวเลขและข้อความส่วนตัวชั่วคราว</label></section><section className="dt-section dt-settings-card"><h3>ส่งออกข้อมูล</h3><p>ไฟล์ส่งออกมีข้อมูลส่วนตัว เก็บไว้ในที่ปลอดภัย</p><div className="dt-actions"><Button onClick={()=>download("daytogether-export.json",JSON.stringify(state,null,2),"application/json")}>ส่งออก JSON</Button><Button onClick={()=>download("daytogether-notes.csv",["หัวข้อ,ประเภท,วันที่,เนื้อหา,แท็ก",...state.notes.map(n=>[n.title,n.kind,n.date,n.body,n.tags.join("|")].map(escapeCsv).map(s=>'"'+s.replace(/"/g,'""')+'"').join(","))].join("\n"),"text/csv;charset=utf-8")}>ส่งออกโน้ต CSV</Button><Button onClick={()=>download("daytogether-savings.csv",csv([["วันที่","ประเภท","จำนวนเงิน (บาท)","เป้าหมาย","หมายเหตุ"],...state.savings.map(x=>[x.date,x.kind,x.amountSatang/100,state.goals.find(g=>g.id===x.goalId)?.name||"ออมทั่วไป",x.note])]),"text/csv;charset=utf-8")}>ส่งออกออมเงิน CSV</Button><Button onClick={()=>download("daytogether-health.csv",csv([["วันที่","หมวด","ค่า","รายละเอียด","หมายเหตุ"],...state.health.map(x=>[x.date,x.kind,x.value,x.extra,x.note])]),"text/csv;charset=utf-8")}>ส่งออกสุขภาพ CSV</Button><Button onClick={()=>download("daytogether-bills.csv",csv([["วันที่","ชื่อบิล","ร้าน","ยอดรวม (บาท)","ผู้ร่วม","รายการค่าใช้จ่าย","สถานะ"],...state.bills.map(b=>[b.date,b.title,b.restaurant,b.expenses.reduce((sum,x)=>sum+x.amountSatang,0)/100,b.participants.map(p=>p.name).join(", "),b.expenses.map(x=>x.title+": "+(x.amountSatang/100)).join(" | "),b.status])]),"text/csv;charset=utf-8")}>ส่งออกหารตัง CSV</Button><Button onClick={()=>download("daytogether-visits.csv",csv([["วันที่","ร้าน","โอกาส","ย่าน","เพื่อน","จำนวนคน","ยอดรวม (บาท)","ส่วนตัว (บาท)","คะแนน","เมนู","ความทรงจำ"],...state.visits.map(v=>[v.date,v.restaurant,v.title,v.area,v.friends,v.people,v.totalSatang==null?"":v.totalSatang/100,v.personalSatang==null?"":v.personalSatang/100,v.rating??"",v.menu,v.memory])]),"text/csv;charset=utf-8")}>ส่งออกมื้ออาหาร CSV</Button><Button variant="danger" onClick={()=>{if(confirm("ลบข้อมูลทุกหมวดของบัญชีนี้หรือไม่? แนะนำให้ส่งออกข้อมูลก่อน")){setState({...defaults,settings:{...defaults.settings,theme}});setNotice("กำลังบันทึกข้อมูล…")}}}>ล้างข้อมูลทุกหมวด</Button></div></section><section className="dt-section dt-settings-card"><h3>ความเป็นส่วนตัว</h3><p>ข้อมูลในหมวดต่าง ๆ แยกจากกัน ไม่มีการหักเงินออมหรือส่งเนื้อหาไดอารีไปในข้อความหารตังโดยอัตโนมัติ การบันทึกการชำระเป็นการบันทึกของผู้ใช้ ไม่ได้ตรวจสอบกับธนาคาร</p><p className="dt-disclaimer">ชื่อ DayTogether เป็นชื่อชั่วคราวที่เปลี่ยนได้ภายหลัง</p></section></div>
    return <div className="dt-page-body"><section className="dt-section"><h3>รายละเอียดเป้าหมาย</h3>{(()=>{const goal=state.goals.find(g=>g.id===routeId);if(!goal)return <Empty title="ไม่พบเป้าหมายนี้" detail="เป้าหมายอาจถูกลบไปแล้ว" action={<Button onClick={()=>go("/savings")}>กลับหน้าออมเงิน</Button>}/>;const saved=state.savings.filter(t=>t.goalId===goal.id).reduce((n,t)=>n+(t.kind==="deposit"?t.amountSatang:-t.amountSatang),0);return <div className="dt-detail-card"><h2>{goal.name}</h2><strong>{money(saved,hidden)} / {money(goal.targetSatang,hidden)}</strong><div className="dt-progress"><i style={{width:Math.min(100,saved/goal.targetSatang*100)+"%"}}/></div><div className="dt-actions"><Button variant="primary" onClick={()=>openModal("saving")}>เพิ่มรายการออม</Button><Button onClick={()=>openModal("goal",goal.id)}>แก้ไขเป้าหมาย</Button><Button variant="danger" onClick={()=>deleteItem("goals",goal.id)}>ลบเป้าหมาย</Button></div></div>})()}</section></div>
  }
  const submitModal = (e:FormEvent<HTMLFormElement>) => {
    e.preventDefault(); const f=new FormData(e.currentTarget)
    if(modal==="goal") { const item:Goal={id:editId||id(),name:String(f.get("name")||"").trim(),targetSatang:amountFrom(f.get("target")),due:String(f.get("due")||""),status:(f.get("status")||"active") as Goal["status"],color:String(f.get("color")||"green")};if(!item.name||item.targetSatang<=0){setNotice("กรุณาระบุชื่อและจำนวนเงินเป้าหมายที่มากกว่า 0");return}update("goals",editId?state.goals.map(g=>g.id===editId?item:g):[item,...state.goals]);setNotice("กำลังบันทึกข้อมูล…")}
    if(modal==="saving") {const amount=amountFrom(f.get("amount")),kind=(f.get("kind")||"deposit") as Saving["kind"],goalId=String(f.get("goalId")||"");const old=state.savings.find(t=>t.id===editId);const otherBalance=state.savings.filter(t=>t.id!==editId&&t.goalId===goalId).reduce((n,t)=>n+(t.kind==="deposit"?t.amountSatang:-t.amountSatang),0);if(!amount){setNotice("จำนวนเงินต้องมากกว่า 0");return}if(kind==="withdraw"&&amount>otherBalance){setNotice("ยอดถอนเกินยอดออมที่เลือก");return}const item:Saving={id:editId||id(),kind,amountSatang:amount,date:String(f.get("date")||today(state.settings.timezone)),goalId,note:String(f.get("note")||"")};update("savings",editId?state.savings.map(t=>t.id===editId?item:t):[item,...state.savings]);setNotice("กำลังบันทึกข้อมูล…")}
    if(modal==="health") {const kind=(f.get("kind")||"weight") as HealthKind;const value=String(f.get("value")||"").trim();if(!value){setNotice("กรุณากรอกค่าที่ต้องการบันทึก");return}const item:Health={id:editId||id(),kind,date:String(f.get("date")||today(state.settings.timezone)),value,extra:String(f.get("extra")||""),note:String(f.get("note")||"")};update("health",editId?state.health.map(h=>h.id===editId?item:h):[item,...state.health]);setNotice("กำลังบันทึกข้อมูล…")}
    if(modal==="visit") {const totalRaw=String(f.get("total")||""),personalRaw=String(f.get("personal")||"");const item:Visit={id:editId||id(),restaurant:String(f.get("restaurant")||"").trim(),title:String(f.get("title")||"").trim(),date:String(f.get("date")||today(state.settings.timezone)),area:String(f.get("area")||""),friends:String(f.get("friends")||""),people:Math.max(1,Number(f.get("people")||1)),totalSatang:totalRaw===""?null:amountFrom(totalRaw),personalSatang:personalRaw===""?null:amountFrom(personalRaw),rating:f.get("rating")?Number(f.get("rating")):null,menu:String(f.get("menu")||""),memory:String(f.get("memory")||""),billId:state.visits.find(v=>v.id===editId)?.billId||""};update("visits",editId?state.visits.map(v=>v.id===editId?item:v):[item,...state.visits]);setNotice("กำลังบันทึกข้อมูล…")}
    if(modal==="bill") {
      const title=String(f.get("title")||"").trim(),rawNames=billPeopleText.split(",").map(n=>n.trim()).filter(Boolean),oldBill=state.bills.find(b=>b.id===editId),meName=oldBill?.participants.find(p=>p.isMe)?.name||"ฉัน";
      if(!title){setNotice("กรุณาตั้งชื่อบิล");return}
      if(oldBill?.settlements.length){setNotice("บิลนี้มีประวัติชำระแล้ว ไม่อนุญาตให้แก้ยอดจนกว่าจะยกเลิกการชำระ");return}
      const uniqueNames=rawNames.filter((name,index)=>name.toLocaleLowerCase()!==meName.toLocaleLowerCase()&&rawNames.findIndex(n=>n.toLocaleLowerCase()===name.toLocaleLowerCase())===index);
      if(!uniqueNames.length){setNotice("เพิ่มชื่อผู้ร่วมอย่างน้อยหนึ่งคนก่อนบันทึกบิล");return}
      const oldByName=new Map((oldBill?.participants||[]).map(p=>[p.name.trim().toLocaleLowerCase(),p]));
      const participants:Participant[]=[{id:oldBill?.participants.find(p=>p.isMe)?.id||id(),name:meName,isMe:true},...uniqueNames.map(name=>({id:oldByName.get(name.toLocaleLowerCase())?.id||id(),name,isMe:false}))];
      const participantByName=new Map(participants.map(p=>[p.name.trim().toLocaleLowerCase(),p]));
      const expenses:Expense[]=[];
      for(const row of billDraftExpenses) {
        const rowTitle=row.title.trim(),amountText=row.amount.trim();
        if(!rowTitle&&!amountText) continue;
        if(!rowTitle||!amountText){setNotice("กรุณากรอกทั้งชื่อและยอดเงินของทุกรายการ");return}
        const amountSatang=amountFrom(amountText);
        if(!Number.isSafeInteger(amountSatang)||amountSatang<=0){setNotice("ยอดเงินแต่ละรายการต้องมากกว่า 0 และอยู่ในช่วงที่รองรับ");return}
        const selectedNames=row.participantNames===null?participants.map(p=>p.name):row.participantNames;
        const selected=selectedNames.map(name=>participantByName.get(name.trim().toLocaleLowerCase())).filter((p):p is Participant=>Boolean(p));
        if(!selected.length){setNotice("เลือกรายชื่อผู้ร่วมรับผิดชอบอย่างน้อยหนึ่งคนในทุกรายการ");return}
        const payer=participantByName.get(row.payerName.trim().toLocaleLowerCase())||participants[0];
        let allocations:Record<string,number>|undefined;
        if(row.allocationMode==="fixed") {
          allocations=Object.fromEntries(selected.map(person=>[person.id,amountFrom(row.allocations[person.name]||"")]));
          if(Object.values(allocations).some(value=>!Number.isSafeInteger(value))||Object.values(allocations).reduce((sum,value)=>sum+value,0)!==amountSatang){setNotice("ยอดที่กำหนดให้แต่ละคนต้องรวมกันเท่ากับยอดรายการ");return}
        } else if(row.allocationMode==="percentage") {
          const percentValues=selected.map(person=>Number(row.allocations[person.name]||""));
          if(percentValues.some(value=>!Number.isFinite(value)||value<0||value>100)){setNotice("เปอร์เซ็นต์ต้องอยู่ระหว่าง 0 ถึง 100");return}
          allocations=Object.fromEntries(selected.map((person,index)=>[person.id,Math.round(percentValues[index]*100)]));
          if(Object.values(allocations).reduce((sum,value)=>sum+value,0)!==10000){setNotice("เปอร์เซ็นต์ของผู้ร่วมรายการต้องรวมกันเท่ากับ 100%");return}
        }
        expenses.push({id:oldBill?.expenses.find(expense=>expense.id===row.key)?.id||id(),title:rowTitle,amountSatang,payerId:payer.id,participantIds:selected.map(person=>person.id),allocationMode:row.allocationMode,...(allocations?{allocations}:{})});
      }
      if(!expenses.length){setNotice("เพิ่มรายการค่าใช้จ่ายอย่างน้อยหนึ่งรายการก่อนบันทึก");return}
      const item:Bill={id:editId||id(),title,date:String(f.get("date")||today(state.settings.timezone)),restaurant:String(f.get("restaurant")||""),participants,expenses,settlements:oldBill?.settlements||[],note:String(f.get("note")||""),bbqId:oldBill?.bbqId||"",status:oldBill?.status||"draft"};
      update("bills",editId?state.bills.map(b=>b.id===editId?item:b):[item,...state.bills]);setNotice("กำลังบันทึกข้อมูล…")
    }
    closeModal()
  }
  const renderModal = () => {
    if(!modal)return null
    const existing=modal==="goal"?state.goals.find(x=>x.id===editId):modal==="saving"?state.savings.find(x=>x.id===editId):modal==="health"?state.health.find(x=>x.id===editId):modal==="visit"?state.visits.find(x=>x.id===editId):modal==="bill"?state.bills.find(x=>x.id===editId):undefined
    return <div className="dt-modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)closeModal()}}><section className="dt-modal" role="dialog" aria-modal="true" aria-labelledby="dt-modal-title"><div className="dt-modal-head"><div><span className="dt-eyebrow">DAYTOGETHER</span><h2 id="dt-modal-title">{modal==="goal"?(editId?"แก้ไขเป้าหมาย":"สร้างเป้าหมายออมเงิน"):modal==="saving"?(editId?"แก้ไขรายการออม":"เพิ่มรายการออม"):modal==="health"?(editId?"แก้ไขบันทึกสุขภาพ":"บันทึกสุขภาพ"):modal==="note"?(editId?"แก้ไขบันทึก":"เขียนบันทึกใหม่"):modal==="bill"?(editId?"แก้ไขบิล":"สร้างบิลหารตัง"):(editId?"แก้ไขประวัติมื้อ":"เพิ่มมื้อหมูกระทะ")}</h2></div><button className="dt-icon-button" onClick={closeModal} aria-label="ปิดหน้าต่าง">×</button></div>
      {modal==="note"?<form className="dt-form" onSubmit={saveNote}><Field label="ประเภท"><select value={draftNote.kind} onChange={e=>setDraftNote(s=>({...s,kind:e.target.value as "note"|"diary"}))}><option value="note">โน้ต</option><option value="diary">ไดอารี</option></select></Field><Field label="หัวข้อ"><input value={draftNote.title} onChange={e=>setDraftNote(s=>({...s,title:e.target.value}))} placeholder="ไม่มีชื่อ หากเว้นว่าง"/></Field><Field label="วันที่"><input type="date" value={draftNote.date} onChange={e=>setDraftNote(s=>({...s,date:e.target.value}))} required/></Field><Field label="เนื้อหา"><textarea rows={7} value={draftNote.body} onChange={e=>setDraftNote(s=>({...s,body:e.target.value}))} placeholder="จดสิ่งที่อยากจำ..." /></Field><Field label="แท็ก (คั่นด้วยจุลภาค)"><input value={draftNote.tags} onChange={e=>setDraftNote(s=>({...s,tags:e.target.value}))} placeholder="งาน, ไอเดีย, ส่วนตัว"/></Field>{draftNote.kind==="diary"&&<Field label="อารมณ์วันนี้"><select value={draftNote.mood} onChange={e=>setDraftNote(s=>({...s,mood:e.target.value}))}><option value="">ไม่ระบุ</option><option>ดีใจ</option><option>เฉยๆ</option><option>เศร้า</option></select></Field>}<div className="dt-modal-actions"><Button onClick={closeModal}>ยกเลิก</Button><Button type="submit" variant="primary">บันทึก</Button></div></form>:<form className="dt-form" onSubmit={submitModal}>
      {modal==="goal"&&<><Field label="ชื่อเป้าหมาย"><input name="name" required defaultValue={(existing as Goal|undefined)?.name||""} placeholder="เช่น ทริปเที่ยว"/></Field><Field label="จำนวนเงินเป้าหมาย (บาท)"><input name="target" type="number" min="0.01" step="0.01" required defaultValue={(existing as Goal|undefined)?.targetSatang?((existing as Goal).targetSatang/100):""}/></Field><Field label="วันที่อยากสำเร็จ (ไม่บังคับ)"><input name="due" type="date" defaultValue={(existing as Goal|undefined)?.due||""}/></Field><Field label="สถานะ"><select name="status" defaultValue={(existing as Goal|undefined)?.status||"active"}><option value="active">กำลังออม</option><option value="done">สำเร็จ</option><option value="archived">เก็บถาวร</option></select></Field><Field label="สี"><select name="color" defaultValue={(existing as Goal|undefined)?.color||"green"}><option value="green">เขียว</option><option value="blue">ฟ้า</option><option value="orange">ส้ม</option><option value="purple">ม่วง</option></select></Field></>}
      {modal==="saving"&&<><Field label="ประเภท"><select name="kind" defaultValue={(existing as Saving|undefined)?.kind|| (kindFilter==="withdraw"?"withdraw":"deposit")}><option value="deposit">ฝากออม</option><option value="withdraw">ถอน</option></select></Field><Field label="จำนวนเงิน (บาท)"><input name="amount" type="number" min="0.01" step="0.01" required defaultValue={(existing as Saving|undefined)?.amountSatang?((existing as Saving).amountSatang/100):""}/></Field><Field label="วันที่"><input name="date" type="date" required defaultValue={(existing as Saving|undefined)?.date||today(state.settings.timezone)}/></Field><Field label="เป้าหมาย"><select name="goalId" defaultValue={(existing as Saving|undefined)?.goalId||""}><option value="">ออมทั่วไป</option>{state.goals.filter(g=>g.status!=="archived").map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field><Field label="หมายเหตุ"><input name="note" defaultValue={(existing as Saving|undefined)?.note||""}/></Field></>}
      {modal==="health"&&<><Field label="หมวด"><select name="kind" defaultValue={(existing as Health|undefined)?.kind|| (kindFilter!=="all"?kindFilter:"weight")}>{state.settings.healthKinds.map(k=><option key={k} value={k}>{KIND_LABEL[k]}</option>)}</select></Field><Field label="ค่า / รายละเอียดสั้น"><input name="value" required defaultValue={(existing as Health|undefined)?.value||""} placeholder="เช่น 72.5, 120/80, 7.5 ชั่วโมง"/></Field><Field label="วันที่และเวลา"><input name="date" type="datetime-local" defaultValue={(existing as Health|undefined)?.date||dateTimeLocal(state.settings.timezone)} required/></Field><Field label="รายละเอียดเพิ่มเติม"><input name="extra" defaultValue={(existing as Health|undefined)?.extra||""} placeholder="เช่น ชีพจร, คุณภาพการนอน, mL"/></Field><Field label="หมายเหตุ"><textarea name="note" rows={3} defaultValue={(existing as Health|undefined)?.note||""}/></Field>{((existing as Health|undefined)?.kind==="water"||kindFilter==="water")&&<div className="dt-quick-water"><Button onClick={()=>{const el=document.querySelector<HTMLInputElement>('input[name="value"]');if(el)el.value="250"}}>＋ 250 mL</Button><Button onClick={()=>{const el=document.querySelector<HTMLInputElement>('input[name="value"]');if(el)el.value="500"}}>＋ 500 mL</Button></div>}</>}
      {modal==="visit"&&<><Field label="ชื่อร้าน"><input name="restaurant" defaultValue={(existing as Visit|undefined)?.restaurant||""} placeholder="ชื่อร้าน"/></Field><Field label="ชื่อมื้อ / โอกาส"><input name="title" defaultValue={(existing as Visit|undefined)?.title||""} placeholder="เช่น นัดเพื่อนวันศุกร์"/></Field><Field label="วันเวลา"><input name="date" type="date" required defaultValue={(existing as Visit|undefined)?.date||today(state.settings.timezone)}/></Field><Field label="สาขา / ย่าน"><input name="area" defaultValue={(existing as Visit|undefined)?.area||""}/></Field><Field label="เพื่อนที่ไปด้วย (คั่นด้วยจุลภาค)"><input name="friends" defaultValue={(existing as Visit|undefined)?.friends||""}/></Field><Field label="จำนวนคน"><input name="people" type="number" min="1" max="100" defaultValue={(existing as Visit|undefined)?.people||1}/></Field><Field label="ยอดรวมทั้งมื้อ (บาท)"><input name="total" type="number" min="0" step="0.01" defaultValue={(existing as Visit|undefined)?.totalSatang===null||!(existing as Visit|undefined)?.totalSatang?"":(existing as Visit).totalSatang!/100}/></Field><Field label="ค่าใช้จ่ายส่วนตัว (บาท)"><input name="personal" type="number" min="0" step="0.01" defaultValue={(existing as Visit|undefined)?.personalSatang===null||!(existing as Visit|undefined)?.personalSatang?"":(existing as Visit).personalSatang!/100}/></Field><Field label="คะแนน 1–5"><select name="rating" defaultValue={(existing as Visit|undefined)?.rating||""}><option value="">ไม่ให้คะแนน</option>{[5,4,3,2,1].map(n=><option key={n} value={n}>{n} ดาว</option>)}</select></Field><Field label="เมนูที่ชอบ"><input name="menu" defaultValue={(existing as Visit|undefined)?.menu||""}/></Field><Field label="ความทรงจำ"><textarea name="memory" rows={4} defaultValue={(existing as Visit|undefined)?.memory||""}/></Field></>}
      {modal==="bill"&&<><Field label="ชื่อบิล"><input name="title" required defaultValue={(existing as Bill|undefined)?.title||""} placeholder="เช่น หมูกระทะวันศุกร์"/></Field><Field label="วัน"><input name="date" type="date" required defaultValue={(existing as Bill|undefined)?.date||today(state.settings.timezone)}/></Field><Field label="ร้าน (ไม่บังคับ)"><input name="restaurant" defaultValue={(existing as Bill|undefined)?.restaurant||""}/></Field><Field label="เพื่อน (คั่นด้วยจุลภาค)"><input name="people" value={billPeopleText} onChange={e=>setBillPeopleText(e.target.value)} placeholder="เช่น มายด์, ต้น, บีม"/></Field>
      <section className="dt-bill-expense-editor"><div className="dt-section-head"><div><h3>รายการค่าใช้จ่าย</h3><p>แยกผู้จ่ายและคนที่ร่วมรับผิดชอบได้ในแต่ละรายการ</p></div><Button onClick={()=>setBillDraftExpenses(rows=>[...rows,{key:id(),title:"",amount:"",payerName:"ฉัน",participantNames:null,allocationMode:"equal",allocations:{}}])}>＋ เพิ่มรายการ</Button></div>
      {billDraftExpenses.map((row,index)=>{const names=["ฉัน",...billPeopleText.split(",").map(name=>name.trim()).filter(Boolean)].filter((name,i,all)=>all.findIndex(other=>other.toLocaleLowerCase()===name.toLocaleLowerCase())===i);const selected=row.participantNames===null?names:row.participantNames;return <article className="dt-bill-expense-row" key={row.key}><div className="dt-bill-expense-row-head"><strong>รายการ {index+1}</strong>{billDraftExpenses.length>1&&<Button variant="ghost" onClick={()=>setBillDraftExpenses(rows=>rows.filter(item=>item.key!==row.key))}>ลบรายการ</Button>}</div><div className="dt-form-grid"><Field label="ชื่อรายการ"><input value={row.title} onChange={e=>setBillDraftExpenses(rows=>rows.map(item=>item.key===row.key?{...item,title:e.target.value}:item))} placeholder="ค่าอาหาร, เครื่องดื่ม…"/></Field><Field label="ยอดเงิน (บาท)"><input type="number" min="0" step="0.01" value={row.amount} onChange={e=>setBillDraftExpenses(rows=>rows.map(item=>item.key===row.key?{...item,amount:e.target.value}:item))} placeholder="0.00"/></Field><Field label="ใครเป็นคนจ่าย"><select value={row.payerName} onChange={e=>setBillDraftExpenses(rows=>rows.map(item=>item.key===row.key?{...item,payerName:e.target.value}:item))}>{names.map(name=><option key={name} value={name}>{name}</option>)}</select></Field><Field label="วิธีแบ่งค่าใช้จ่าย"><select value={row.allocationMode} onChange={e=>setBillDraftExpenses(rows=>rows.map(item=>item.key===row.key?{...item,allocationMode:e.target.value as BillExpenseDraft["allocationMode"]}:item))}><option value="equal">หารเท่ากัน</option><option value="fixed">กำหนดยอดแต่ละคน</option><option value="percentage">กำหนดเปอร์เซ็นต์</option></select></Field></div><div className="dt-bill-participants"><strong>ใครร่วมรายการนี้</strong><div>{names.map(name=><label key={name}><input type="checkbox" checked={selected.includes(name)} onChange={e=>setBillDraftExpenses(rows=>rows.map(item=>{if(item.key!==row.key)return item;const current=item.participantNames===null?names:item.participantNames;return {...item,participantNames:e.target.checked?[...new Set([...current,name])]:current.filter(person=>person!==name)}}))}/><span>{name}</span></label>)}</div></div>
      {row.allocationMode!=="equal"&&<div className="dt-bill-allocation-grid"><strong>{row.allocationMode==="fixed"?"ยอดที่แต่ละคนรับผิดชอบ (บาท)":"สัดส่วนของแต่ละคน (%)"}</strong>{selected.map(name=><Field key={name} label={name}><input type="number" min="0" step={row.allocationMode==="fixed"?"0.01":"0.01"} value={row.allocations[name]||""} onChange={e=>setBillDraftExpenses(rows=>rows.map(item=>item.key===row.key?{...item,allocations:{...item.allocations,[name]:e.target.value}}:item))} placeholder={row.allocationMode==="fixed"?"0.00":"0"}/></Field>)}</div>}</article>})}
      </section><div className="dt-bill-total-preview" aria-live="polite"><span>ยอดรวมรายการ ({billDraftExpenses.filter(row=>row.title.trim()||row.amount.trim()).length} รายการ)</span><strong>{money(billDraftExpenses.reduce((sum,row)=>{const amount=amountFrom(row.amount);return sum+(Number.isSafeInteger(amount)&&amount>0?amount:0)},0),hidden)}</strong><small>ยอดจะคำนวณจากรายการที่กรอกจำนวนเงินถูกต้อง และตรวจสัดส่วนอีกครั้งก่อนบันทึก</small></div><Field label="หมายเหตุ"><textarea name="note" rows={3} defaultValue={(existing as Bill|undefined)?.note||""}/></Field><p className="dt-form-hint">ระบบจะตรวจให้ยอดแบ่งรวมเท่ากับยอดรายการก่อนบันทึก เพื่อไม่ให้ยอดหายหรือเกิน</p></>}
      <div className="dt-modal-actions"><Button onClick={closeModal}>ยกเลิก</Button><Button type="submit" variant="primary">บันทึก</Button></div></form>}
      </section></div>
  }
  return <div className="dt-app"><aside className="dt-sidebar"><button className="dt-brand" onClick={()=>go("/")}><span className="dt-brand-mark">d.</span><span><strong>DayTogether</strong><small>พื้นที่ส่วนตัว</small></span></button><div className="dt-nav-label">เมนูหลัก</div><nav className="dt-nav">{navItems.map(href=><button key={href} className={page===href?"active":""} onClick={()=>go(href)}><span>{ICON[href]}</span>{PAGE_LABEL[href]}</button>)}</nav><div className="dt-sidebar-bottom"><button className={page==="/settings"?"active":""} onClick={()=>go("/settings")}><span>⚙</span>ตั้งค่า</button><div className="dt-private-note">ข้อมูลส่วนตัว<br/><strong>พื้นที่ของคุณเท่านั้น</strong></div></div></aside>
    <main className="dt-main"><header className="dt-topbar"><div className="dt-breadcrumb"><span>DayTogether</span><b>/</b><strong>{pageTitle}</strong></div><div className="dt-top-actions"><button className={hidden?"dt-privacy active":"dt-privacy"} onClick={()=>setState(s=>({...s,settings:{...s.settings,hidden:!s.settings.hidden}}))} aria-label={hidden?"แสดงข้อมูล":"ซ่อนข้อมูล"}>{hidden?"◉":"◎"}<span>{hidden?"แสดงข้อมูล":"ซ่อนข้อมูล"}</span></button><button className="dt-avatar" onClick={()=>go("/settings")} aria-label="เปิดตั้งค่า">{(state.settings.displayName||"D").slice(0,1).toUpperCase()}</button></div></header><div className="dt-content"><div className="dt-page-heading"><div><span className="dt-eyebrow">YOUR PERSONAL SPACE</span><h1>{pageTitle}</h1></div>{page!=="/"&&page!=="/settings"&&page!=="/404"&&path===page&&<Button variant="primary" onClick={()=>openModal(page==="/savings"?"saving":page==="/health"?"health":page==="/notes"?"note":page==="/split"?"bill":"visit")}>＋ เพิ่มรายการ</Button>}</div>{pageBody()}</div></main>
    <nav className="dt-mobile-nav" aria-label="เมนูหลัก">{["/","/savings","/health","/notes","more"].map(href=><button key={href} className={(href==="more"?(moreOpen||page==="/split"||page==="/bbq"||page==="/settings"):page===href)?"active":""} onClick={()=>href==="more"?setMoreOpen(v=>!v):go(href)}><span>{href==="more"?"＋":ICON[href]}</span><small>{href==="more"?"เพิ่มเติม":PAGE_LABEL[href]}</small></button>)}</nav>
    {moreOpen&&<><button className="dt-sheet-dismiss" aria-label="ปิดเมนูเพิ่มเติม" onClick={()=>setMoreOpen(false)}/><section className="dt-more-sheet"><div className="dt-sheet-handle"/><h3>เพิ่มเติม</h3>{["/split","/bbq","/settings"].map(href=><button key={href} onClick={()=>go(href)}><span>{ICON[href]}</span>{PAGE_LABEL[href]}<b>↗</b></button>)}</section></>}
    {renderModal()}
    {notice&&<div className="dt-toast" role="status"><span>✓</span>{notice}<button onClick={()=>setNotice("")} aria-label="ปิด">×</button></div>}
  </div>
}

function BillDetail({bill,hidden,onBack,onEdit,onDelete,onSaveSettlement,onLinkVisit,onCancelSettlement}:{bill:Bill;hidden:boolean;onBack:()=>void;onEdit:()=>void;onDelete:()=>void;onSaveSettlement:(from:string,to:string,amount:number,note:string)=>void;onLinkVisit:()=>void;onCancelSettlement:(id:string)=>void}) {
  const [from,setFrom]=useState("");const [to,setTo]=useState("");const [amount,setAmount]=useState("");const [note,setNote]=useState("")
  const summary=calculateSplit(bill.expenses,bill.participants,bill.settlements)
  const total=bill.expenses.reduce((n,e)=>n+e.amountSatang,0)
  const me=bill.participants.find(p=>p.isMe)
  const netTransfers=summary.transfers
  const name=(pid:string)=>bill.participants.find(p=>p.id===pid)?.name||"ผู้ร่วมบิล"
  return <div className="dt-page-body"><Button onClick={onBack}>← กลับรายการบิล</Button><article className="dt-detail-card"><div className="dt-detail-top"><span className={"dt-pill "+bill.status}>{bill.status==="settled"?"เคลียร์แล้ว":bill.status==="settling"?"กำลังเคลียร์":"ร่าง"}</span><span>{dateText(bill.date)}</span></div><h2>{bill.title}</h2><p>{bill.restaurant||"ไม่ระบุร้าน"} · {bill.participants.length} คน</p><div className="dt-stat-grid three"><div className="dt-inline-stat"><small>ยอดรวม</small><strong>{money(total,hidden)}</strong></div><div className="dt-inline-stat"><small>จำนวนคน</small><strong>{bill.participants.length}</strong></div><div className="dt-inline-stat"><small>ประวัติชำระ</small><strong>{bill.settlements.length} รายการ</strong></div></div><h3>รายการค่าใช้จ่าย</h3>{bill.expenses.map(e=><div className="dt-list-row" key={e.id}><span className="dt-list-copy"><strong>{e.title}</strong><small>คนจ่าย: {name(e.payerId)} · หาร {e.participantIds.length} คน</small></span><strong>{money(e.amountSatang,hidden)}</strong></div>)}<h3>ส่วนที่แต่ละคนรับผิดชอบ</h3>{bill.participants.map(p=><div className="dt-list-row" key={p.id}><span className="dt-list-copy"><strong>{p.name}{p.isMe?" (ฉัน)":""}</strong><small>{summary.balances[p.id]>0?"สำรองจ่ายเกินส่วน":summary.balances[p.id]<0?"ยังต้องจ่าย":"ยอดพอดี"}</small></span><strong>{money(Math.abs(summary.balances[p.id]||0),hidden)}{summary.balances[p.id]>0?" · ต้องรับ":summary.balances[p.id]<0?" · ต้องจ่าย":""}</strong></div>)}<h3>แนะนำการเคลียร์เงิน</h3>{netTransfers.length?netTransfers.map((t,i)=><div className="dt-transfer" key={i}><span>{name(t.fromId)} <b>โอนให้</b> {name(t.toId)}</span><strong>{money(t.amountSatang,hidden)}</strong></div>):<p>ยังไม่มียอดสุทธิที่ต้องเคลียร์</p>}<h3>บันทึกการชำระ</h3>{bill.settlements.length?bill.settlements.map(s=><div className="dt-list-row" key={s.id}><span className="dt-list-copy"><strong>{name(s.fromId)} โอนให้ {name(s.toId)}</strong><small>{dateText(s.date)} {s.note}</small></span><strong>{money(s.amountSatang,hidden)}</strong><Button variant="danger" onClick={()=>onCancelSettlement(s.id)}>ยกเลิก</Button></div>):<p>ยังไม่มีรายการชำระ</p>}<form className="dt-settlement-form" onSubmit={e=>{e.preventDefault();const n=amountFrom(amount);if(!from||!to||from===to||n<=0)return;onSaveSettlement(from,to,n,note);setAmount("");setNote("")}}><h3>บันทึกว่าโอนเคลียร์แล้ว</h3><div className="dt-form-grid"><Field label="ผู้โอน"><select value={from} onChange={e=>setFrom(e.target.value)} required><option value="">เลือกผู้โอน</option>{bill.participants.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="ผู้รับ"><select value={to} onChange={e=>setTo(e.target.value)} required><option value="">เลือกผู้รับ</option>{bill.participants.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="จำนวนเงิน (บาท)"><input type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} required/></Field><Field label="หมายเหตุ"><input value={note} onChange={e=>setNote(e.target.value)}/></Field></div><Button type="submit" variant="primary">บันทึกการชำระ</Button></form>{me&&<p className="dt-disclaimer">การทำเครื่องหมายว่าโอนแล้วเป็นการบันทึกของผู้ใช้ ไม่ใช่การตรวจสอบจากธนาคาร</p>}<div className="dt-actions"><Button onClick={onEdit} disabled={bill.settlements.length>0}>แก้ไขยอดและผู้ร่วมบิล</Button><Button onClick={onLinkVisit}>{bill.bbqId?"เปิดมื้อที่เชื่อม":"บันทึกเป็นมื้อหมูกระทะ"}</Button><Button variant="danger" onClick={onDelete}>ลบบิล</Button></div></article></div>
}
